      String name, {
      Iterable<String> allow = const [],
      Iterable<String> mounts = const [],
      String? networkAllowHost,
      String? cachePaths,
      String? backend,
    }) {
      final sections = <String>[
        if (backend != null) '  backend: $backend',
        '  tools:',
        '    allow: [${allow.join(', ')}]',
        if (mounts.isNotEmpty)
