      final server = await MockLlmServer.start();
      addTearDown(server.stop);
      final cube = writeCube('fs-guard', mounts: ['path: /etc, access: deny']);
      server.enqueueToolCall('read', '{"path":"/etc/hostname"}');
      server.enqueueToolResultEcho();

