  _KernelRun? _kernelRunFor(CubeSpec spec) {
    final fs = _fs;
    final os = _os;
    if (spec.backend != CubeBackendMode.kernel || fs == null || os == null) {
      return null;
    }
    final backend = cubeBackendForPlatform(
      os,
      spec: spec,
      workspaceRoot: fs.cwd,
      tmpdir: '${fs.cwd}/.fah/tmp',
