  void updateSpec(CubeSpec spec) {
    _spec = spec;
    _engine = CubePolicyEngine(
      spec,
      homeDir: _homeDir,
      workspaceRoot: _fs?.cwd,
    );
    _kernel = _kernelRunFor(spec);
