  /// Leaves sandbox mode: every command is forwarded untouched.
  void clearSpec() {
    _spec = null;
    _kernel = null;
  }

  /// Binds the kernel backend for a `backend: kernel` spec, or `null` when
  /// the run stays in pure policy mode: no filesystem to stage with, no
