      : const CubeNetworkPolicy(),
  filesystem: const CubeFsPolicy(
    workspace: '/workspace',
    mounts: [
      CubeMount(path: '/usr/share', access: CubePathAccess.readOnly),
      CubeMount(path: '/etc', access: CubePathAccess.deny),
