      expect(
        first.exitCode,
        0,
        reason: 'stdout: ${first.stdout}\nstderr: ${first.stderr}',
      );

      final cacheRoot = Directory('${workspace.path}/.fah/cube-cache');
      expect(
        cacheRoot.existsSync(),
        isTrue,
        reason: 'cache root written on exit',
