        if (networkAllowHost != null)
          '  network:\n'
              '    allow:\n'
              '      - {host: $networkAllowHost}',
        if (cachePaths != null)
          '  cache:\n'
              '    enabled: true\n'
              '    paths: [$cachePaths]',
      ];
      File('${workspace.path}/.fah/cubes/$name.yaml')
        ..createSync(recursive: true)
        ..writeAsStringSync(
          'apiVersion: fa/v1\n'
          'kind: Cube\n'
          'metadata:\n'
          '  name: $name\n'
          'spec:\n'
          '${sections.join('\n')}\n',
        );
      return name;
    }

