    if (spec == null) return _inner.exec(command, options: options);
    final decision = _engine.checkCommand(command);
    if (!decision.allowed) {
      return Ok(
        ShellExecResult(
          stdout: '',
          stderr: 'fa_cube[${spec.name}]: ${decision.reason}',
          exitCode: 127,
