        profile,
        contains('(deny file-read* (subpath "/private/etc/hosts"))'),
      );
      expect(profile, contains('(allow file-read* (subpath "/etc"))'));
      expect(profile, contains('(allow file-read* (subpath "/private/etc"))'));
