    });

    test('escapes embedded single quotes', () {
      expect(shellQuote("git commit -m 'hi'"), "'git commit -m '\\''hi'\\'''");
    });

    test('quotes the empty string', () {
      expect(shellQuote(''), "''");
    });
  });

